    "css": "html, body { background: #0b0c0c !important; color: #efefe8; }\n.pp-page-background { background: repeating-linear-gradient(125deg, #131514 0 1px, transparent 1px 34px), #0b0c0c !important; }\n.profile-background-effect-image { display: none; }\nmain, .profile-page-container { padding: 0 !important; }\n.pp-uc-background, .pp-uc-background > div, .profile-info-wrapper-box { width: 100% !important; max-width: none !important; background: transparent !important; box-shadow: none !important; padding: 0 !important; }\n.profile-page-flex { display: block !important; width: 100% !important; max-width: none !important; }\n.profile-info-stack { position: relative; display: flex !important; flex-direction: column; gap: 0 !important; width: min(1440px, calc(100% - 64px)) !important; max-width: none !important; margin: 28px auto 65px !important; padding: 0 !important; font-family: Arial, Helvetica, sans-serif; }\n.profile-info-hstack { position: relative; display: flex !important; flex-direction: row !important; align-items: center; justify-content: flex-start; gap: 25px !important; width: 100%; min-height: 236px; margin: 0 !important; padding: 42px 38px 35px !important; border: 2px solid #3c4035; border-radius: 18px 18px 0 0; overflow: hidden; background: linear-gradient(108deg, #171a16 0 69%, #d7f22a 69.2% 70.2%, #aebf2a 70.3% 71%, #d7f22a 71.2%); isolation: isolate; }\n.profile-info-hstack::before { content: \"INTER-KNOT  /  CREATOR CHANNEL\"; position: absolute; top: 17px; left: 40px; color: #d7f22a; font-size: 9px; font-weight: 900; letter-spacing: .24em; }\n.profile-info-hstack::after { content: \"PROXY\"; position: absolute; z-index: -1; right: -2px; top: 28px; color: #141813; font-size: clamp(65px, 8.5vw, 132px); font-weight: 1000; line-height: 1; letter-spacing: -.09em; font-style: italic; transform: rotate(-8deg); opacity: .92; }\n.pp-uc-avatar-container { flex: 0 0 128px; width: 128px !important; height: 140px !important; padding: 5px; border: 2px solid #d7f22a; border-radius: 13px 5px 13px 5px; background: #070908; transform: rotate(-4deg); }\n.pp-uc-avatar { display: block; width: 100% !important; height: 100% !important; object-fit: cover; object-position: center; border-radius: 7px !important; }\n.profile-info-stack-inner { gap: 7px !important; min-width: 0; max-width: 57%; align-items: flex-start !important; }\n.profile-info-stack-inner-flex { margin: 0 !important; gap: 5px; }\n.pp-uc-title { margin: 0 !important; color: #f2f2e9 !important; font-family: Arial, Helvetica, sans-serif !important; font-size: clamp(26px, 3.5vw, 48px) !important; font-weight: 1000 !important; font-style: italic; letter-spacing: -.06em; line-height: 1.05 !important; overflow-wrap: anywhere; }\n.pp-uc-followers-count { color: #d7f22a !important; font-size: 12px !important; font-weight: 800; letter-spacing: .04em; }\n.pp-uc-member-since { color: #939a8b !important; font-size: 9px !important; text-transform: uppercase; letter-spacing: .11em; }\n.profile-badges { display: flex; flex-wrap: wrap; gap: 7px !important; }\n.profile-badge, .profile-badge img { width: 25px !important; height: 25px !important; }\n.pp-uc-about-me { display: block; width: 100%; max-width: none; margin: 0 !important; padding: 0 !important; color: #efefe8; font-family: Arial, Helvetica, sans-serif; }\n.pp-uc-about-me *, .pp-uc-about-me *::before, .pp-uc-about-me *::after { box-sizing: border-box; }\n.pp-uc-about-me h1, .pp-uc-about-me h2, .pp-uc-about-me h3, .pp-uc-about-me p { margin: 0; }\n.pp-uc-about-me a { text-decoration: none; }\n.profile-info-stack > div:has(> button[aria-label=\"Customize profile page\"]) { right: 10px; top: 10px; z-index: 15; }\n@media (max-width: 800px) {\n  .profile-info-stack { width: calc(100% - 24px) !important; margin: 16px auto 80px !important; }\n  .profile-info-hstack { gap: 15px !important; min-height: 260px; padding: 44px 20px 78px !important; background: linear-gradient(108deg, #171a16 0 77%, #d7f22a 77.2%); }\n  .profile-info-hstack::before { left: 21px; font-size: 8px; }\n  .profile-info-hstack::after { right: -26px; top: 105px; font-size: 59px; transform: rotate(-90deg); opacity: .7; }\n  .pp-uc-avatar-container { flex-basis: 85px; width: 85px !important; height: 103px !important; }\n  .profile-info-stack-inner { max-width: calc(100% - 122px); }\n  .pp-uc-title { font-size: clamp(21px, 4.8vw, 33px) !important; }\n  .profile-badge, .profile-badge img { width: 19px !important; height: 19px !important; }\n}\n",
