    "css": ".pp-top-bar { background: #111310 !important; }\n.pp-top-bar-outer { z-index: 100 !important; border-bottom: 2px solid #d7f22a !important; background: #111310 !important; box-shadow: 0 6px 0 #0006 !important; }\n.pp-top-bar-inner { background: transparent !important; }\n.pp-top-bar-logo, .pp-top-bar-logo-name, .glow-logo { color: #e7f1bf !important; text-shadow: none !important; }\n.pp-top-bar-search-input, .pp-top-bar-search-box { border: 1px solid #414733 !important; border-radius: 999px !important; background: #242820 !important; color: #f2f4e7 !important; }\n.pp-top-bar-app-menu { border: 2px solid #d7f22a !important; border-radius: 50% !important; }\n.pp-top-bar-app-menu-list, .pp-uc-options-menu-list, [role=\"menu\"], .pp-top-bar-notifications-popover { background: #191d16 !important; color: #f4f7e6 !important; border: 1px solid #626c43 !important; border-radius: 12px !important; box-shadow: 0 14px 40px #000b !important; }\n.pp-top-bar-app-menu-list-item, .pp-uc-options-menu-item { color: #edf1df !important; background: transparent !important; }\n.pp-top-bar-app-menu-list-item:hover, .pp-uc-options-menu-item:hover { color: #e2ff51 !important; background: #303726 !important; }\n.profile-info-stack > div:has(.pp-uc-follow-flex) { position: absolute; top: 174px; right: 28px; z-index: 12; margin: 0 !important; }\n.profile-info-stack > div:has(.pp-uc-follow-flex) > div { display: flex; flex-direction: row; align-items: center; gap: 9px; }\n.pp-uc-follow-button { display: flex !important; align-items: center; justify-content: center; min-width: 123px; min-height: 40px; height: auto !important; padding: 10px 18px !important; border: 2px solid #11150d !important; border-radius: 7px !important; background: #11150d !important; color: #e6ff6a !important; box-shadow: 3px 3px 0 #829513 !important; font-size: 12px; font-weight: 900; }\n.pp-uc-follow-button::before { display: none !important; }\n.pp-uc-follow-text { color: inherit !important; font-size: 12px !important; font-weight: 900; }\n.pp-uc-follow-button:hover { background: #2d351f !important; }\n.pp-uc-options-menu { display: inline-flex !important; min-height: 40px; padding: 10px 15px !important; border: 2px solid #11150d !important; border-radius: 7px !important; background: #d7f22a !important; color: #11150d !important; font-size: 12px !important; font-weight: 900; }\n.pp-uc-options-menu:hover { background: #edff8e !important; }\n.pp-mnb-container, .pp-mnb { background: #11150d !important; border-top: 1px solid #56602f; }\n.pp-mnb a { color: #d7f22a !important; }\n@media (max-width: 800px) {\n  .profile-info-stack > div:has(.pp-uc-follow-flex) { top: 207px; left: 20px; right: auto; }\n  .pp-uc-follow-button, .pp-uc-options-menu { min-height: 34px; padding: 6px 12px !important; }\n}\n",
