    "css": ".zz-nav-key { position: fixed; top: 72px; left: 0; width: 1px; height: 1px; pointer-events: none; }\n.zz-navigation { position: relative; z-index: 20; display: flex; align-items: stretch; gap: 5px; min-height: 68px; padding: 12px 20px; border: 2px solid #34382e; border-top: 0; background: #10130f; }\n.zz-nav { display: flex; align-items: center; flex-wrap: wrap; gap: 5px; }\n.zz-tab { display: flex; align-items: center; gap: 12px; min-height: 40px; padding: 10px 20px; border: 1px solid transparent; border-radius: 5px; color: #979e8b !important; font-size: 12px; font-weight: 900; font-style: italic; text-transform: uppercase; transform: skewX(-9deg); transition: background .18s ease, color .18s ease; }\n.zz-tab small { font-size: 9px; opacity: .6; font-style: normal; }\n.zz-tab-agents { background: #d7f22a; color: #11150c !important; box-shadow: 3px 3px 0 #607016; }\n.zz-tab:hover { border-color: #d7f22a; color: #ecff8b !important; background: #29311d; }\n.zz-nav-meta { display: flex; align-items: center; gap: 8px; margin-left: auto; color: #a5af90; font-size: 8px; font-weight: 900; letter-spacing: .15em; }\n.zz-nav-meta i { width: 6px; height: 6px; background: #d7f22a; border-radius: 50%; box-shadow: 0 0 10px #d7f22a80; }\n.zz-screen { min-height: 620px; background: #10120f; border: 2px solid #34382e; border-top: 0; }\n.zz-personal { display: none; }\n.pp-uc-about-me:has(#zz-about:target, #zz-friends:target, #zz-links:target) .zz-agents { display: none; }\n.pp-uc-about-me:has(#zz-about:target) .zz-about-screen,\n.pp-uc-about-me:has(#zz-friends:target) .zz-friends-screen,\n.pp-uc-about-me:has(#zz-links:target) .zz-links-screen { display: block; }\n.pp-uc-about-me:has(#zz-about:target, #zz-friends:target, #zz-links:target) .zz-tab-agents { background: transparent; color: #979e8b !important; box-shadow: none; }\n.pp-uc-about-me:has(#zz-about:target) .zz-tab-about,\n.pp-uc-about-me:has(#zz-friends:target) .zz-tab-friends,\n.pp-uc-about-me:has(#zz-links:target) .zz-tab-links { background: #d7f22a; color: #11150c !important; box-shadow: 3px 3px 0 #607016; }\n.zz-footer { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding: 14px 19px; background: #d7f22a; color: #19200e; border-radius: 0 0 12px 12px; font-size: 9px; font-weight: 900; letter-spacing: .06em; text-transform: uppercase; }\n.zz-footer a { color: #19200e !important; }\n.pp-uc-about-me a:focus-visible, .pp-uc-about-me summary:focus-visible { outline: 3px solid #f8ffae; outline-offset: 4px; }\n@media (max-width: 800px) {\n  .zz-navigation { padding: 9px 8px; min-height: 58px; }\n  .zz-nav { width: 100%; justify-content: space-between; gap: 3px; }\n  .zz-tab { padding: 9px 12px; gap: 6px; font-size: 11px; }\n  .zz-nav-meta { display: none; }\n  .zz-screen { min-height: 610px; }\n}\n@media (max-width: 430px) { .zz-tab { padding: 9px 10px; font-size: 10px; } .zz-tab small { display: none; } .zz-footer { font-size: 8px; } }\n",
    "html": "<div class=\"zz-navigation\"><span class=\"zz-nav-key\" id=\"zz-agents\"></span><span class=\"zz-nav-key\" id=\"zz-about\"></span><span class=\"zz-nav-key\" id=\"zz-friends\"></span><span class=\"zz-nav-key\" id=\"zz-links\"></span><nav class=\"zz-nav\" aria-label=\"Profile screens\"><a class=\"zz-tab zz-tab-agents\" href=\"#zz-agents\"><small>01</small> Agents</a><a class=\"zz-tab zz-tab-about\" href=\"#zz-about\"><small>02</small> About me</a><a class=\"zz-tab zz-tab-friends\" href=\"#zz-friends\"><small>03</small> Friends</a><a class=\"zz-tab zz-tab-links\" href=\"#zz-links\"><small>04</small> Links</a></nav><span class=\"zz-nav-meta\"><i></i> PERSONAL TERMINAL</span></div>\n",
